    static Optional<QuestEntry> byQuestId(int questId) {
        for (QuestEntry entry : entries()) {
            if (entry.questId() == questId) return Optional.of(entry);
        }
        return Optional.empty();
    }

    static Optional<QuestEntry> byRowId(int rowId) {
        for (QuestEntry entry : entries()) {
            if (entry.rowId() == rowId) return Optional.of(entry);
        }
        return Optional.empty();
    }

